export declare const styles = "\n:where(.jrl-lesson) {\n  color: var(--jrl-text, #14243a); font: 1rem/1.5 system-ui, sans-serif;\n}\n:where(.jrl-lesson *, .jrl-viewport *) { box-sizing: border-box; }\n:where(.jrl-lesson) { display: grid; grid-template-columns: minmax(0, 1.6fr) minmax(0, 1fr); gap: 1rem; }\n:where(.jrl-visual) { min-width: 0; }\n:where(.jrl-sidebar) {\n  border: 1px solid var(--jrl-border, #cad6e3); background: var(--jrl-surface, #f4f7fb);\n  padding: 1.25rem; border-radius: var(--jrl-radius, .9rem); min-width: 0; display: flex;\n  flex-direction: column; gap: 1rem;\n}\n:where(.jrl-copy) { display: grid; gap: .4rem; }\n:where(.jrl-title) { font-size: 1.25rem; line-height: 1.25; margin: 0; }\n:where(.jrl-description) { margin: 0; color: var(--jrl-muted, #465b71); white-space: pre-line; }\n:where(div.jrl-math) { overflow-x: auto; overflow-y: hidden; padding-block: .12em; }\n:where(.jrl-equation) { min-width: 0; padding: .35rem 0; }\n:where(.jrl-progress) { color: var(--jrl-muted, #465b71); font-size: .875rem; margin: 0; }\n:where(.jrl-controls) { display: grid; gap: .8rem; }\n:where(.jrl-control-label) { display: flex; align-items: baseline; justify-content: space-between; gap: .5rem; }\n:where(.jrl-control output) { font-variant-numeric: tabular-nums; color: var(--jrl-accent, #096680); }\n:where(.jrl-control input) { width: 100%; margin: .35rem 0 0; accent-color: var(--jrl-accent, #096680); }\n:where(.jrl-navigation) { display: flex; gap: .5rem; margin-top: auto; }\n:where(.jrl-button) {\n  color: inherit; background: transparent; border: 1px solid var(--jrl-border, #cad6e3);\n  padding: .45rem .8rem; border-radius: .5rem; font: inherit; cursor: pointer;\n}\n:where(.jrl-next) { background: var(--jrl-accent, #096680); color: var(--jrl-on-accent, #fff); border-color: transparent; }\n:where(.jrl-button:disabled) { opacity: .5; cursor: default; }\n:where(.jrl-button:focus-visible, .jrl-control input:focus-visible, .jrl-canvas:focus-visible) {\n  outline: 2px solid var(--jrl-accent, #096680); outline-offset: 3px;\n}\n:where(.jrl-viewport) {\n  box-sizing: border-box; margin: 0; width: 100%; min-width: 0; overflow: hidden;\n  border: 1px solid var(--jrl-border, #cad6e3); border-radius: var(--jrl-radius, .9rem);\n}\n:where(.jrl-viewport canvas, .jrl-viewport svg) { display: block; width: 100%; height: 100%; }\n:where(.jrl-orbit) { touch-action: none; cursor: grab; }\n:where(.jrl-orbit:active) { cursor: grabbing; }\n@media (max-width: 700px) { :where(.jrl-lesson) { grid-template-columns: minmax(0, 1fr); } }\n";
